function Test-RecordAdapter {
  param([Parameter(Mandatory = $true)][string]$Path)
  $record = Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json
  if (-not $record.record_id) { throw 'Missing record_id' }
  [pscustomobject]@{ component = 'RecordAdapter'; record_id = $record.record_id; status = 'parsed' }
}
Export-ModuleMember -Function Test-RecordAdapter
